-- 1. ENUM DE ROLES
create type public.app_role as enum (
  'admin',
  'gestor_financeiro',
  'coordenador_campo',
  'auditor',
  'consultor'
);

-- 2. TABELA DE PERFIS
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  nome_completo text not null,
  cargo text,
  email text not null,
  avatar_url text,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

alter table public.profiles enable row level security;

-- 3. TABELA DE USER ROLES (SEGURANÇA CRÍTICA)
create table public.user_roles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade not null,
  role app_role not null,
  created_at timestamp with time zone default now(),
  created_by uuid references auth.users(id),
  unique (user_id, role)
);

alter table public.user_roles enable row level security;

-- 4. FUNÇÃO SECURITY DEFINER PARA VERIFICAR ROLES
create or replace function public.has_role(_user_id uuid, _role app_role)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.user_roles
    where user_id = _user_id
      and role = _role
  )
$$;

-- 5. TRIGGER PARA CRIAR PERFIL AUTOMÁTICO
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'nome_completo', 'Usuário'),
    new.email
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- 6. TABELA DE CATEGORIAS (12 categorias do Excel)
create table public.categorias (
  id uuid primary key default gen_random_uuid(),
  nome text not null unique,
  descricao text,
  cor text default '#9CAF96',
  ativo boolean default true,
  ordem integer,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

alter table public.categorias enable row level security;

-- Inserir as 12 categorias do Excel

-- 7. TABELA DE LANÇAMENTOS (estrutura exata do Excel)
create table public.lancamentos (
  id uuid primary key default gen_random_uuid(),
  
  -- Campos principais (colunas do Excel)
  item text not null,
  observacao text,
  justificativa text,
  tipo_quantitativo text,
  valor_quantitativo numeric(15,2),
  metrica text,
  valor_metrica numeric(15,2),
  valor_unitario numeric(15,2),
  realizado numeric(15,2) not null check (realizado >= 0),
  mes text not null,
  ano integer not null check (ano >= 2020 and ano <= 2050),
  grupo_item text not null,
  
  -- Campos de referência
  categoria_id uuid references public.categorias(id),
  usuario_id uuid references auth.users(id) not null,
  
  -- Campos de auditoria
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

alter table public.lancamentos enable row level security;

-- Índices para performance
create index idx_lancamentos_mes_ano on public.lancamentos(mes, ano);
create index idx_lancamentos_categoria on public.lancamentos(categoria_id);
create index idx_lancamentos_grupo_item on public.lancamentos(grupo_item);
create index idx_lancamentos_usuario on public.lancamentos(usuario_id);

-- 8. TABELA DE ORÇAMENTO PLANEJADO
create table public.orcamento_planejado (
  id uuid primary key default gen_random_uuid(),
  categoria_id uuid references public.categorias(id) on delete cascade not null,
  mes text not null,
  ano integer not null check (ano >= 2020 and ano <= 2050),
  valor_orcado numeric(15,2) not null check (valor_orcado >= 0),
  observacao text,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  unique (categoria_id, mes, ano)
);

alter table public.orcamento_planejado enable row level security;

create index idx_orcamento_mes_ano on public.orcamento_planejado(mes, ano);

-- 9. FUNÇÃO PARA ATUALIZAR updated_at
create or replace function public.update_updated_at_column()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- Triggers para updated_at
create trigger update_profiles_updated_at
  before update on public.profiles
  for each row execute function public.update_updated_at_column();

create trigger update_categorias_updated_at
  before update on public.categorias
  for each row execute function public.update_updated_at_column();

create trigger update_lancamentos_updated_at
  before update on public.lancamentos
  for each row execute function public.update_updated_at_column();

create trigger update_orcamento_updated_at
  before update on public.orcamento_planejado
  for each row execute function public.update_updated_at_column();

-- =====================================================
-- ROW LEVEL SECURITY POLICIES
-- =====================================================

-- RLS: PROFILES
create policy "Users can view own profile"
  on public.profiles for select
  using (auth.uid() = id);

create policy "Users can update own profile"
  on public.profiles for update
  using (auth.uid() = id);

create policy "Admins can view all profiles"
  on public.profiles for select
  using (public.has_role(auth.uid(), 'admin'));

create policy "Admins can update all profiles"
  on public.profiles for update
  using (public.has_role(auth.uid(), 'admin'));

-- RLS: USER ROLES
create policy "Users can view own roles"
  on public.user_roles for select
  using (auth.uid() = user_id);

create policy "Admins can manage all roles"
  on public.user_roles for all
  using (public.has_role(auth.uid(), 'admin'));

-- RLS: CATEGORIAS
create policy "Authenticated users can view categories"
  on public.categorias for select
  to authenticated
  using (true);

create policy "Gestores can manage categories"
  on public.categorias for all
  using (
    public.has_role(auth.uid(), 'admin') or 
    public.has_role(auth.uid(), 'gestor_financeiro')
  );

-- RLS: LANÇAMENTOS
create policy "Authenticated users can view lancamentos"
  on public.lancamentos for select
  to authenticated
  using (true);

create policy "Gestores can create lancamentos"
  on public.lancamentos for insert
  to authenticated
  with check (
    public.has_role(auth.uid(), 'admin') or 
    public.has_role(auth.uid(), 'gestor_financeiro') or
    public.has_role(auth.uid(), 'coordenador_campo')
  );

create policy "Users can update own lancamentos or gestores all"
  on public.lancamentos for update
  using (
    usuario_id = auth.uid() or
    public.has_role(auth.uid(), 'admin') or
    public.has_role(auth.uid(), 'gestor_financeiro')
  );

create policy "Only admins can delete lancamentos"
  on public.lancamentos for delete
  using (public.has_role(auth.uid(), 'admin'));

-- RLS: ORÇAMENTO PLANEJADO
create policy "Authenticated users can view budget"
  on public.orcamento_planejado for select
  to authenticated
  using (true);

create policy "Gestores can manage budget"
  on public.orcamento_planejado for all
  using (
    public.has_role(auth.uid(), 'admin') or 
    public.has_role(auth.uid(), 'gestor_financeiro')
  );

