-- Função para detectar alertas automaticamente
CREATE OR REPLACE FUNCTION public.detectar_alertas(ano_referencia INTEGER)
RETURNS TABLE (
  tipo_alerta TEXT,
  severidade TEXT,
  categoria_nome TEXT,
  categoria_id UUID,
  mes TEXT,
  mensagem TEXT,
  valor_orcado NUMERIC,
  valor_realizado NUMERIC,
  delta_percentual NUMERIC,
  acao_sugerida TEXT
) 
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  -- Alerta de excesso orçamentário
  WITH comparativo AS (
    SELECT 
      op.categoria_id,
      c.nome as cat_nome,
      op.mes,
      op.ano,
      op.valor_orcado,
      COALESCE(SUM(l.realizado), 0) as total_realizado,
      CASE 
        WHEN op.valor_orcado > 0 THEN
          ROUND(((COALESCE(SUM(l.realizado), 0) - op.valor_orcado) / op.valor_orcado * 100), 2)
        ELSE 0
      END as delta_pct
    FROM orcamento_planejado op
    JOIN categorias c ON op.categoria_id = c.id
    LEFT JOIN lancamentos l ON l.categoria_id = op.categoria_id AND l.mes = op.mes AND l.ano = op.ano
    WHERE op.ano = ano_referencia
    GROUP BY op.categoria_id, c.nome, op.mes, op.ano, op.valor_orcado
  )
  -- Excesso orçamentário (> 20%)
  SELECT 
    'excesso_orcamentario'::TEXT,
    CASE 
      WHEN delta_pct > 100 THEN 'critico'::TEXT
      WHEN delta_pct > 50 THEN 'alto'::TEXT
      ELSE 'medio'::TEXT
    END,
    cat_nome,
    categoria_id,
    mes,
    FORMAT('Categoria %s excedeu orçamento em %s%% no mês de %s', cat_nome, ROUND(delta_pct, 1), mes)::TEXT,
    valor_orcado,
    total_realizado,
    delta_pct,
    'Revisar reclassificação de despesas ou solicitar suplementação orçamentária'::TEXT
  FROM comparativo
  WHERE delta_pct > 20
  
  UNION ALL
  
  -- Subutilização (< -50%)
  SELECT 
    'subutilizacao'::TEXT,
    CASE 
      WHEN delta_pct < -80 THEN 'alto'::TEXT
      ELSE 'medio'::TEXT
    END,
    cat_nome,
    categoria_id,
    mes,
    FORMAT('Categoria %s subutilizada em %s%% no mês de %s', cat_nome, ROUND(ABS(delta_pct), 1), mes)::TEXT,
    valor_orcado,
    total_realizado,
    delta_pct,
    'Verificar se houve adiamento ou cancelamento de atividades'::TEXT
  FROM comparativo
  WHERE delta_pct < -50
  
  ORDER BY ABS(delta_pct) DESC;
END;
$$;

