-- Criar função para atribuir role admin ao primeiro usuário
CREATE OR REPLACE FUNCTION public.assign_admin_to_first_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Verificar se é o primeiro usuário (profiles vazio ou apenas 1 registro)
  IF (SELECT COUNT(*) FROM public.profiles) <= 1 THEN
    -- Inserir role admin
    VALUES (NEW.id, 'admin')
    ON CONFLICT (user_id, role) DO NOTHING;
  END IF;
  
  RETURN NEW;
END;
$$;

-- Criar trigger que executa após inserção de profile
DROP TRIGGER IF EXISTS assign_admin_on_first_profile ON public.profiles;
CREATE TRIGGER assign_admin_on_first_profile
AFTER INSERT ON public.profiles
FOR EACH ROW
EXECUTE FUNCTION public.assign_admin_to_first_user();

