-- Função para criar notificação quando alerta é criado
CREATE OR REPLACE FUNCTION public.notificar_novo_alerta()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  usuario_record RECORD;
BEGIN
  -- Para cada usuário com notificações de alertas ativadas
  FOR usuario_record IN 
    SELECT p.id, p.notificacoes_alertas, p.email
    FROM profiles p
    WHERE p.notificacoes_alertas = true
  LOOP
    -- Criar notificação
      user_id,
      tipo,
      titulo,
      mensagem,
      link,
      metadata
    ) VALUES (
      usuario_record.id,
      'alerta',
      'Novo Alerta Detectado',
      NEW.mensagem,
      '/dashboard',
      jsonb_build_object(
        'alerta_id', NEW.id,
        'severidade', NEW.severidade,
        'categoria', NEW.tipo_alerta
      )
    );
  END LOOP;
  
  RETURN NEW;
END;
$$;

-- Trigger para alertas
CREATE TRIGGER trigger_notificar_novo_alerta
  AFTER INSERT ON public.alertas_dashboard
  FOR EACH ROW
  EXECUTE FUNCTION public.notificar_novo_alerta();

-- Habilitar realtime para notificações
ALTER PUBLICATION supabase_realtime ADD TABLE public.notificacoes;

