-- Atualizar função para chamar edge function de envio de email
CREATE OR REPLACE FUNCTION public.notificar_novo_alerta()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  usuario_record RECORD;
  notificacao_id UUID;
  payload JSONB;
BEGIN
  -- Para cada usuário com notificações de alertas ativadas
  FOR usuario_record IN 
    SELECT p.id, p.notificacoes_alertas, p.email
    FROM profiles p
    WHERE p.notificacoes_alertas = true
  LOOP
    -- Criar notificação
      user_id,
      tipo,
      titulo,
      mensagem,
      link,
      metadata
    ) VALUES (
      usuario_record.id,
      'alerta',
      'Novo Alerta Detectado',
      NEW.mensagem,
      '/dashboard',
      jsonb_build_object(
        'alerta_id', NEW.id,
        'severidade', NEW.severidade,
        'categoria', NEW.tipo_alerta
      )
    )
    RETURNING id INTO notificacao_id;

    -- Chamar edge function para enviar email (via pg_net se disponível)
    -- Nota: isso tentará chamar a função, mas não bloqueará se falhar
    BEGIN
      -- Preparar payload para edge function
      payload := jsonb_build_object(
        'user_id', usuario_record.id,
        'titulo', 'Novo Alerta Detectado',
        'mensagem', NEW.mensagem,
        'tipo', 'alerta',
        'link', 'https://gbsrxqvlfaixyjjmimqs.supabase.co/dashboard'
      );
      
      -- Tentar fazer request HTTP (requer extensão pg_net)
