CREATE OR REPLACE FUNCTION public.notificar_alerta_resolvido()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  usuario_record RECORD;
  payload JSONB;
BEGIN
  -- Apenas notificar se o alerta foi marcado como resolvido
  IF NEW.resolvido = true AND (OLD.resolvido IS NULL OR OLD.resolvido = false) THEN
    -- Para cada usuário com notificações de alertas ativadas
    FOR usuario_record IN 
      SELECT p.id, p.notificacoes_alertas, p.email
      FROM profiles p
      WHERE p.notificacoes_alertas = true
    LOOP
      -- Criar notificação
        user_id,
        tipo,
        titulo,
        mensagem,
        link,
        metadata
      ) VALUES (
        usuario_record.id,
        'sistema',
        'Alerta Resolvido',
        FORMAT('Alerta "%s" foi marcado como resolvido', NEW.mensagem),
        '/dashboard',
        jsonb_build_object(
          'alerta_id', NEW.id,
          'severidade', NEW.severidade,
          'resolvido_por', NEW.resolvido_por
        )
      );

      -- Chamar edge function para enviar email
      BEGIN
        payload := jsonb_build_object(
          'user_id', usuario_record.id,
          'titulo', 'Alerta Resolvido',
          'mensagem', FORMAT('Alerta "%s" foi marcado como resolvido', NEW.mensagem),
          'tipo', 'sistema',
          'link', 'https://gbsrxqvlfaixyjjmimqs.supabase.co/dashboard'
        );
        
        PERFORM net.http_post(
          url := 'https://gbsrxqvlfaixyjjmimqs.supabase.co/functions/v1/enviar-notificacao-email',
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || current_setting('request.headers')::json->>'authorization'
          ),
          body := payload
        );
      EXCEPTION
        WHEN OTHERS THEN
          RAISE NOTICE 'Erro ao chamar edge function de email: %', SQLERRM;
      END;
    END LOOP;
  END IF;
  
  RETURN NEW;
END;
$$;

