-- 1. Criar tabela de auditoria
CREATE TABLE IF NOT EXISTS public.auditoria_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- Identificação da operação
  tabela TEXT NOT NULL,
  operacao TEXT NOT NULL CHECK (operacao IN ('INSERT', 'UPDATE', 'DELETE')),
  registro_id UUID NOT NULL,
  
  -- Dados da mudança
  dados_antigos JSONB,
  dados_novos JSONB,
  campos_alterados TEXT[],
  
  -- Contexto do usuário
  usuario_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome TEXT,
  usuario_email TEXT,
  usuario_roles TEXT[],
  
  -- Metadados
  ip_address TEXT,
  user_agent TEXT,
  timestamp TIMESTAMPTZ NOT NULL DEFAULT now(),
  
  -- Informações adicionais
  observacao TEXT,
  metadata JSONB
);

-- 2. Criar índices para performance
CREATE INDEX IF NOT EXISTS idx_auditoria_tabela ON public.auditoria_logs(tabela);
CREATE INDEX IF NOT EXISTS idx_auditoria_operacao ON public.auditoria_logs(operacao);
CREATE INDEX IF NOT EXISTS idx_auditoria_usuario ON public.auditoria_logs(usuario_id);
CREATE INDEX IF NOT EXISTS idx_auditoria_timestamp ON public.auditoria_logs(timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_auditoria_registro ON public.auditoria_logs(registro_id);

-- 3. Habilitar RLS
ALTER TABLE public.auditoria_logs ENABLE ROW LEVEL SECURITY;

-- 4. Policies RLS
CREATE POLICY "Admins and auditors can view audit logs"
ON public.auditoria_logs FOR SELECT
TO authenticated
USING (
  public.has_role(auth.uid(), 'admin'::app_role) OR 
  public.has_role(auth.uid(), 'auditor'::app_role)
);

CREATE POLICY "System can insert audit logs"
ON public.auditoria_logs FOR INSERT
TO authenticated
WITH CHECK (true);

-- 5. Função genérica de auditoria
CREATE OR REPLACE FUNCTION public.registrar_auditoria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_usuario_id UUID;
  v_usuario_nome TEXT;
  v_usuario_email TEXT;
  v_usuario_roles TEXT[];
  v_campos_alterados TEXT[];
  v_key TEXT;
BEGIN
  -- Obter usuário autenticado
  v_usuario_id := auth.uid();
  
  -- Buscar informações do usuário
  SELECT nome_completo, email INTO v_usuario_nome, v_usuario_email
  FROM public.profiles WHERE id = v_usuario_id;
  
  -- Buscar roles do usuário
  SELECT array_agg(role::TEXT) INTO v_usuario_roles
  FROM public.user_roles WHERE user_id = v_usuario_id;
  
  -- Identificar campos alterados (apenas para UPDATE)
  IF TG_OP = 'UPDATE' THEN
    v_campos_alterados := ARRAY[]::TEXT[];
    FOR v_key IN SELECT jsonb_object_keys(to_jsonb(NEW))
    LOOP
      IF to_jsonb(OLD)->>v_key IS DISTINCT FROM to_jsonb(NEW)->>v_key THEN
        v_campos_alterados := array_append(v_campos_alterados, v_key);
      END IF;
    END LOOP;
  END IF;
  
  -- Inserir log de auditoria
    tabela,
    operacao,
    registro_id,
    dados_antigos,
    dados_novos,
    campos_alterados,
    usuario_id,
    usuario_nome,
    usuario_email,
    usuario_roles
  ) VALUES (
    TG_TABLE_NAME,
    TG_OP,
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD)
         WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD)
         ELSE NULL END,
    CASE WHEN TG_OP = 'INSERT' THEN to_jsonb(NEW)
         WHEN TG_OP = 'UPDATE' THEN to_jsonb(NEW)
         ELSE NULL END,
    v_campos_alterados,
    v_usuario_id,
    v_usuario_nome,
    v_usuario_email,
    v_usuario_roles
  );
  
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- 6. Criar triggers para auditoria

-- 6.1 Lancamentos
DROP TRIGGER IF EXISTS trigger_audit_lancamentos ON public.lancamentos;
CREATE TRIGGER trigger_audit_lancamentos
AFTER INSERT OR UPDATE OR DELETE ON public.lancamentos
FOR EACH ROW EXECUTE FUNCTION public.registrar_auditoria();

