AFTER INSERT OR UPDATE OR DELETE ON public.user_roles
FOR EACH ROW EXECUTE FUNCTION public.registrar_auditoria();

-- 6.4 Alertas Dashboard (apenas quando resolvido muda)
DROP TRIGGER IF EXISTS trigger_audit_alertas_dashboard ON public.alertas_dashboard;
