-- FASE 14: INTEGRAÇÕES AVANÇADAS E AUTOMAÇÕES

-- ====================================
-- 1. WORKFLOWS E APROVAÇÕES
-- ====================================

-- Enum para status de aprovação
CREATE TYPE status_aprovacao AS ENUM ('pendente', 'aprovado', 'rejeitado', 'cancelado');

-- Enum para tipos de workflow
CREATE TYPE tipo_workflow AS ENUM ('orcamento', 'lancamento', 'meta', 'categoria');

-- Tabela de workflows de aprovação
CREATE TABLE workflows_aprovacao (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo tipo_workflow NOT NULL,
  registro_id UUID NOT NULL,
  solicitante_id UUID NOT NULL,
  aprovador_id UUID,
  status status_aprovacao DEFAULT 'pendente' NOT NULL,
  nivel_aprovacao INTEGER DEFAULT 1,
  justificativa TEXT,
  observacoes_aprovador TEXT,
  dados_solicitacao JSONB NOT NULL,
  prazo_aprovacao TIMESTAMPTZ,
  aprovado_em TIMESTAMPTZ,
  criado_em TIMESTAMPTZ DEFAULT now(),
  atualizado_em TIMESTAMPTZ DEFAULT now()
);

-- Índices para workflows
CREATE INDEX idx_workflows_status ON workflows_aprovacao(status);
CREATE INDEX idx_workflows_solicitante ON workflows_aprovacao(solicitante_id);
CREATE INDEX idx_workflows_aprovador ON workflows_aprovacao(aprovador_id);
CREATE INDEX idx_workflows_prazo ON workflows_aprovacao(prazo_aprovacao) WHERE status = 'pendente';

-- RLS Policies para workflows
ALTER TABLE workflows_aprovacao ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own requests"
  ON workflows_aprovacao FOR SELECT
  USING (solicitante_id = auth.uid() OR aprovador_id = auth.uid());

CREATE POLICY "Users can create workflows"
  ON workflows_aprovacao FOR INSERT
  WITH CHECK (solicitante_id = auth.uid());

CREATE POLICY "Approvers can update workflows"
  ON workflows_aprovacao FOR UPDATE
  USING (aprovador_id = auth.uid() OR has_role(auth.uid(), 'admin'));

-- Trigger para notificar aprovador
CREATE OR REPLACE FUNCTION notificar_novo_workflow()
RETURNS TRIGGER AS $$
BEGIN
    user_id,
    tipo,
    titulo,
    mensagem,
    link,
    metadata
  ) VALUES (
    NEW.aprovador_id,
    'aprovacao',
    'Nova Solicitação de Aprovação',
    FORMAT('Você tem uma nova solicitação de aprovação de %s pendente', NEW.tipo),
    '/aprovacoes',
    jsonb_build_object('workflow_id', NEW.id, 'tipo', NEW.tipo)
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE TRIGGER trigger_notificar_workflow
  AFTER INSERT ON workflows_aprovacao
  FOR EACH ROW
  EXECUTE FUNCTION notificar_novo_workflow();

-- Trigger para notificar solicitante após aprovação/rejeição
CREATE OR REPLACE FUNCTION notificar_resultado_workflow()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status != OLD.status AND NEW.status IN ('aprovado', 'rejeitado') THEN
      user_id,
      tipo,
      titulo,
      mensagem,
      link,
      metadata
    ) VALUES (
      NEW.solicitante_id,
      'aprovacao',
      CASE 
        WHEN NEW.status = 'aprovado' THEN 'Solicitação Aprovada'
        ELSE 'Solicitação Rejeitada'
      END,
      FORMAT('Sua solicitação de %s foi %s', NEW.tipo, NEW.status),
      '/aprovacoes',
      jsonb_build_object('workflow_id', NEW.id, 'status', NEW.status)
    );
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

