-- Criar tabela de orçamento detalhado
CREATE TABLE public.orcamento_detalhado (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ano INTEGER NOT NULL,
  mes TEXT NOT NULL,
  categoria_principal TEXT NOT NULL,
  categoria_id UUID REFERENCES public.categorias(id) ON DELETE SET NULL,
  item_nome TEXT NOT NULL,
  memoria_calculo TEXT,
  observacao TEXT,
  
  -- Métricas de quantidade
  unidade_1 TEXT,
  quantidade_1 NUMERIC,
  unidade_2 TEXT,
  quantidade_2 NUMERIC,
  
  -- Valores
  valor_unitario NUMERIC NOT NULL DEFAULT 0,
  valor_subtotal NUMERIC GENERATED ALWAYS AS (
    COALESCE(quantidade_1, 1) * COALESCE(quantidade_2, 1) * valor_unitario
  ) STORED,
  
  -- Metadados
  ordem INTEGER DEFAULT 0,
  ativo BOOLEAN DEFAULT true,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  
  -- Constraint para evitar valores negativos
  CHECK (valor_unitario >= 0),
  CHECK (quantidade_1 IS NULL OR quantidade_1 >= 0),
  CHECK (quantidade_2 IS NULL OR quantidade_2 >= 0)
);

