-- Criar view para saldo orçamentário por item
CREATE OR REPLACE VIEW vw_saldo_orcamentario_itens AS
SELECT 
  i.id as item_id,
  i.nome as item_nome,
  i.quantidade_orcada_anual,
  i.unidade_1,
  i.ano_base,
  COALESCE(SUM(l.valor_quantitativo), 0) as quantidade_realizada,
  COALESCE(i.quantidade_orcada_anual - SUM(l.valor_quantitativo), i.quantidade_orcada_anual) as saldo_disponivel,
  CASE 
    WHEN i.quantidade_orcada_anual > 0 
    THEN ROUND((COALESCE(SUM(l.valor_quantitativo), 0) / i.quantidade_orcada_anual * 100), 2)
    ELSE 0 
  END as percentual_executado
FROM itens_despesa i
LEFT JOIN lancamentos l ON l.item = i.nome AND l.ano = i.ano_base
WHERE i.ativo = true
GROUP BY i.id, i.nome, i.quantidade_orcada_anual, i.unidade_1, i.ano_base;

-- Habilitar RLS na view
ALTER VIEW vw_saldo_orcamentario_itens SET (security_invoker = true);

-- Criar função para verificar alertas orçamentários
CREATE OR REPLACE FUNCTION verificar_alertas_orcamentarios()
RETURNS TRIGGER AS $$
DECLARE
  v_saldo NUMERIC;
  v_item_nome TEXT;
  v_categoria_id UUID;
BEGIN
  -- Buscar saldo disponível do item
  SELECT saldo_disponivel, item_nome 
  INTO v_saldo, v_item_nome
  FROM vw_saldo_orcamentario_itens 
  WHERE item_nome = NEW.item AND ano_base = NEW.ano;
  
  -- Se não encontrou o item na view, retornar
  IF v_item_nome IS NULL THEN
    RETURN NEW;
  END IF;
  
  -- Inserir alerta se houver estouro (saldo negativo)
  IF v_saldo < 0 THEN
      tipo_alerta,
      severidade,
      mensagem,
      categoria_id,
      ano,
      mes
    ) VALUES (
      'estouro_quantitativo',
      'critico',
      'Item "' || NEW.item || '" ultrapassou a quantidade orçada em ' || ABS(v_saldo) || ' unidades',
      NEW.categoria_id,
      NEW.ano,
      NEW.mes
    );
  END IF;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Criar trigger para alertas automáticos
DROP TRIGGER IF EXISTS trigger_alerta_estouro_orcamento ON lancamentos;
CREATE TRIGGER trigger_alerta_estouro_orcamento
AFTER INSERT OR UPDATE ON lancamentos
FOR EACH ROW
EXECUTE FUNCTION verificar_alertas_orcamentarios();

