-- Criar view para calcular saldo residual
CREATE OR REPLACE VIEW public.vw_saldo_residual_projeto AS
SELECT 
  otp.id,
  otp.ano_inicio,
  otp.mes_inicio,
  otp.ano_fim,
  otp.mes_fim,
  otp.item_nome,
  otp.grupo_item,
  otp.categoria_principal,
  otp.valor_total_projeto,
  otp.unidade,
  otp.quantidade_total,
  
  -- Somar lançamentos de Março/2025 a Agosto/2025
  COALESCE(SUM(
    CASE 
      WHEN l.ano = 2025 AND l.mes IN ('março', 'abril', 'maio', 'junho', 'julho', 'agosto')
      THEN l.realizado 
      ELSE 0 
    END
  ), 0) AS total_realizado_ate_agosto,
  
  -- Calcular saldo residual
  otp.valor_total_projeto - COALESCE(SUM(
    CASE 
      WHEN l.ano = 2025 AND l.mes IN ('março', 'abril', 'maio', 'junho', 'julho', 'agosto')
      THEN l.realizado 
      ELSE 0 
    END
  ), 0) AS saldo_residual,
  
  -- Percentual executado
  CASE 
    WHEN otp.valor_total_projeto > 0 
    THEN ROUND((COALESCE(SUM(
      CASE 
        WHEN l.ano = 2025 AND l.mes IN ('março', 'abril', 'maio', 'junho', 'julho', 'agosto')
        THEN l.realizado 
        ELSE 0 
      END
    ), 0) / otp.valor_total_projeto * 100), 2)
    ELSE 0 
  END AS percentual_executado,
  
  -- 6 meses restantes: Set/2025 a Fev/2026
  6 AS meses_restantes,
  
  -- Valor mensal médio para distribuir
  ROUND((otp.valor_total_projeto - COALESCE(SUM(
    CASE 
      WHEN l.ano = 2025 AND l.mes IN ('março', 'abril', 'maio', 'junho', 'julho', 'agosto')
      THEN l.realizado 
      ELSE 0 
    END
  ), 0)) / 6, 2) AS valor_mensal_distribuir

FROM public.orcamento_total_projeto otp
LEFT JOIN public.lancamentos l ON 
  l.item = otp.item_nome 
  AND l.grupo_item = otp.grupo_item
WHERE otp.ativo = true
GROUP BY 
  otp.id, 
  otp.ano_inicio, 
  otp.mes_inicio, 
  otp.ano_fim, 
  otp.mes_fim, 
  otp.item_nome, 
  otp.grupo_item, 
  otp.categoria_principal, 
  otp.valor_total_projeto,
  otp.unidade,
  otp.quantidade_total;

-- Migration: 20251104115501_00d994bf-76cd-4277-b30e-270206c89d78.sql
-- Função para calcular saldo residual dinamicamente baseado no mês de corte
CREATE OR REPLACE FUNCTION public.calcular_saldo_residual(
  p_ano_corte INTEGER,
  p_mes_corte TEXT
)
RETURNS TABLE (
  id UUID,
  ano_inicio INTEGER,
  mes_inicio TEXT,
  ano_fim INTEGER,
  mes_fim TEXT,
  item_nome TEXT,
  grupo_item TEXT,
  categoria_principal TEXT,
  valor_total_projeto NUMERIC,
  unidade TEXT,
  quantidade_total NUMERIC,
  total_realizado_ate_corte NUMERIC,
  saldo_residual NUMERIC,
  percentual_executado NUMERIC,
  meses_restantes INTEGER,
  valor_mensal_distribuir NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_meses_restantes INTEGER;
  v_ordem_mes_corte INTEGER;
BEGIN
  -- Mapear mês de corte para número de meses restantes
  -- Projeto vai de Março/2025 a Fevereiro/2026
  -- Set=5 meses restantes, Out=4, Nov=3, Dez=2, Jan=1, Fev=0
  v_ordem_mes_corte := CASE LOWER(p_mes_corte)
    WHEN 'março' THEN 0
    WHEN 'abril' THEN 1
    WHEN 'maio' THEN 2
    WHEN 'junho' THEN 3
    WHEN 'julho' THEN 4
    WHEN 'agosto' THEN 5
    WHEN 'setembro' THEN 6
    WHEN 'outubro' THEN 7
    WHEN 'novembro' THEN 8
    WHEN 'dezembro' THEN 9
    WHEN 'janeiro' THEN 10
    WHEN 'fevereiro' THEN 11
    ELSE 5 -- default agosto
  END;

  -- Calcular meses restantes (total 12 meses - mês atual - 1)
  -- Se estamos em agosto (ordem 5), restam 6 meses (set-fev)
  -- Se estamos em setembro (ordem 6), restam 5 meses (out-fev)
  v_meses_restantes := GREATEST(0, 11 - v_ordem_mes_corte);

  RETURN QUERY
  SELECT 
    otp.id,
    otp.ano_inicio,
    otp.mes_inicio,
    otp.ano_fim,
    otp.mes_fim,
    otp.item_nome,
    otp.grupo_item,
    otp.categoria_principal,
    otp.valor_total_projeto,
    otp.unidade,
    otp.quantidade_total,
    
    -- Total realizado até o mês de corte
    COALESCE(SUM(
      CASE 
        WHEN (l.ano = 2025 AND CASE LOWER(l.mes)
              WHEN 'março' THEN 0
              WHEN 'abril' THEN 1
              WHEN 'maio' THEN 2
              WHEN 'junho' THEN 3
              WHEN 'julho' THEN 4
              WHEN 'agosto' THEN 5
              WHEN 'setembro' THEN 6
              WHEN 'outubro' THEN 7
              WHEN 'novembro' THEN 8
              WHEN 'dezembro' THEN 9
              ELSE 99
            END <= v_ordem_mes_corte)
        OR (l.ano = 2026 AND CASE LOWER(l.mes)
              WHEN 'janeiro' THEN 10
              WHEN 'fevereiro' THEN 11
              ELSE 99
            END <= v_ordem_mes_corte)
        THEN l.realizado
        ELSE 0
      END
    ), 0) AS total_realizado_ate_corte,
    
    -- Saldo residual
    (otp.valor_total_projeto - COALESCE(SUM(
      CASE 
        WHEN (l.ano = 2025 AND CASE LOWER(l.mes)
              WHEN 'março' THEN 0
              WHEN 'abril' THEN 1
              WHEN 'maio' THEN 2
              WHEN 'junho' THEN 3
              WHEN 'julho' THEN 4
              WHEN 'agosto' THEN 5
              WHEN 'setembro' THEN 6
              WHEN 'outubro' THEN 7
              WHEN 'novembro' THEN 8
              WHEN 'dezembro' THEN 9
              ELSE 99
            END <= v_ordem_mes_corte)
        OR (l.ano = 2026 AND CASE LOWER(l.mes)
              WHEN 'janeiro' THEN 10
              WHEN 'fevereiro' THEN 11
              ELSE 99
            END <= v_ordem_mes_corte)
        THEN l.realizado
        ELSE 0
      END
    ), 0)) AS saldo_residual,
    
    -- Percentual executado
    CASE 
      WHEN otp.valor_total_projeto > 0 
      THEN ROUND((COALESCE(SUM(
        CASE 
          WHEN (l.ano = 2025 AND CASE LOWER(l.mes)
                WHEN 'março' THEN 0
                WHEN 'abril' THEN 1
                WHEN 'maio' THEN 2
                WHEN 'junho' THEN 3
                WHEN 'julho' THEN 4
                WHEN 'agosto' THEN 5
                WHEN 'setembro' THEN 6
                WHEN 'outubro' THEN 7
                WHEN 'novembro' THEN 8
                WHEN 'dezembro' THEN 9
                ELSE 99
              END <= v_ordem_mes_corte)
          OR (l.ano = 2026 AND CASE LOWER(l.mes)
                WHEN 'janeiro' THEN 10
                WHEN 'fevereiro' THEN 11
                ELSE 99
              END <= v_ordem_mes_corte)
          THEN l.realizado
          ELSE 0
        END
      ), 0) / otp.valor_total_projeto * 100)::NUMERIC, 2)
      ELSE 0 
    END AS percentual_executado,
    
    v_meses_restantes AS meses_restantes,
    
    -- Valor mensal a distribuir
    CASE 
      WHEN v_meses_restantes > 0 
      THEN ROUND(((otp.valor_total_projeto - COALESCE(SUM(
        CASE 
          WHEN (l.ano = 2025 AND CASE LOWER(l.mes)
                WHEN 'março' THEN 0
                WHEN 'abril' THEN 1
                WHEN 'maio' THEN 2
                WHEN 'junho' THEN 3
                WHEN 'julho' THEN 4
                WHEN 'agosto' THEN 5
                WHEN 'setembro' THEN 6
                WHEN 'outubro' THEN 7
                WHEN 'novembro' THEN 8
                WHEN 'dezembro' THEN 9
                ELSE 99
              END <= v_ordem_mes_corte)
          OR (l.ano = 2026 AND CASE LOWER(l.mes)
                WHEN 'janeiro' THEN 10
                WHEN 'fevereiro' THEN 11
                ELSE 99
              END <= v_ordem_mes_corte)
          THEN l.realizado
          ELSE 0
        END
      ), 0)) / v_meses_restantes)::NUMERIC, 2)
      ELSE 0
    END AS valor_mensal_distribuir

  FROM public.orcamento_total_projeto otp
  LEFT JOIN public.lancamentos l ON 
    l.item = otp.item_nome 
    AND l.grupo_item = otp.grupo_item
  WHERE otp.ativo = true
  GROUP BY 
    otp.id, 
    otp.ano_inicio,
    otp.mes_inicio,
    otp.ano_fim,
    otp.mes_fim,
    otp.item_nome, 
    otp.grupo_item, 
    otp.categoria_principal, 
    otp.valor_total_projeto,
    otp.unidade,
    otp.quantidade_total;
END;
$$;

