-- Criar função para normalizar nomes de itens
CREATE OR REPLACE FUNCTION public.normalizar_nome_item(nome TEXT)
RETURNS TEXT AS $$
BEGIN
  -- Remove espaços extras, converte para Title Case, remove acentos opcionalmente
  RETURN initcap(trim(regexp_replace(nome, '\s+', ' ', 'g')));
END;
$$ LANGUAGE plpgsql IMMUTABLE;

