                WHEN 'março' THEN 0
                WHEN 'abril' THEN 1
                WHEN 'maio' THEN 2
                WHEN 'junho' THEN 3
                WHEN 'julho' THEN 4
                WHEN 'agosto' THEN 5
                WHEN 'setembro' THEN 6
                WHEN 'outubro' THEN 7
