              END <= v_ordem_mes_corte)
          THEN l.realizado
          ELSE 0
        END
      ), 0) / otp.valor_total_projeto * 100)::NUMERIC, 2)
      ELSE 0 
    END AS percentual_executado,
    
    v_meses_restantes AS meses_restantes,
    
    -- Valor mensal a distribuir
    CASE 
      WHEN v_meses_restantes > 0 
      THEN ROUND(((otp.valor_total_projeto - COALESCE(SUM(
        CASE 
          WHEN (l.ano = 2025 AND CASE LOWER(l.mes)
                WHEN 'março' THEN 0
                WHEN 'abril' THEN 1
                WHEN 'maio' THEN 2
                WHEN 'junho' THEN 3
                WHEN 'julho' THEN 4
                WHEN 'agosto' THEN 5
                WHEN 'setembro' THEN 6
                WHEN 'outubro' THEN 7
                WHEN 'novembro' THEN 8
                WHEN 'dezembro' THEN 9
                ELSE 99
              END <= v_ordem_mes_corte)
          OR (l.ano = 2026 AND CASE LOWER(l.mes)
                WHEN 'janeiro' THEN 10
                WHEN 'fevereiro' THEN 11
                ELSE 99
              END <= v_ordem_mes_corte)
          THEN l.realizado
          ELSE 0
        END
      ), 0)) / v_meses_restantes)::NUMERIC, 2)
      ELSE 0
    END AS valor_mensal_distribuir

  FROM public.orcamento_total_projeto otp
  LEFT JOIN public.lancamentos l ON 
    -- Usar normalização para comparação case-insensitive e sem espaços extras
    normalizar_nome_item(l.item) = normalizar_nome_item(otp.item_nome) 
    AND normalizar_nome_item(l.grupo_item) = normalizar_nome_item(otp.grupo_item)
  WHERE otp.ativo = true
  GROUP BY 
    otp.id, 
    otp.ano_inicio,
    otp.mes_inicio,
    otp.ano_fim,
    otp.mes_fim,
    otp.item_nome, 
    otp.grupo_item, 
    otp.categoria_principal, 
    otp.valor_total_projeto,
    otp.unidade,
    otp.quantidade_total;
END;
$function$;

