-- ============================================================
-- FASE 1: LIMPEZA DE DUPLICATAS E PADRONIZAÇÃO
-- ============================================================

-- 1.1: Limpar duplicatas em orcamento_total_projeto (soft delete)
WITH duplicatas AS (
  SELECT 
    item_nome,
    grupo_item,
    MAX(created_at) as ultima_criacao
  FROM orcamento_total_projeto
  WHERE ativo = true
  GROUP BY item_nome, grupo_item
  HAVING COUNT(*) > 1
),
registros_manter AS (
  SELECT otp.id
  FROM orcamento_total_projeto otp
  INNER JOIN duplicatas d ON 
    otp.item_nome = d.item_nome 
    AND otp.grupo_item = d.grupo_item
    AND otp.created_at = d.ultima_criacao
)
UPDATE orcamento_total_projeto
SET ativo = false, updated_at = NOW()
WHERE id NOT IN (SELECT id FROM registros_manter)
  AND ativo = true
  AND (item_nome, grupo_item) IN (
    SELECT item_nome, grupo_item 
    FROM orcamento_total_projeto 
    WHERE ativo = true
    GROUP BY item_nome, grupo_item 
    HAVING COUNT(*) > 1
  );

-- 1.2: Padronizar nomes de grupos em orcamento_total_projeto
UPDATE orcamento_total_projeto
SET grupo_item = 'Alimentos e Bebidas', updated_at = NOW()
WHERE LOWER(grupo_item) = 'alimentos e bebidas';

UPDATE orcamento_total_projeto
SET grupo_item = 'Outras Despesas Administrativas FLEM', updated_at = NOW()
WHERE LOWER(grupo_item) = 'outras despesas administrativas flem';

UPDATE orcamento_total_projeto
SET grupo_item = 'Prestador de Serviços PJ', updated_at = NOW()
WHERE grupo_item IN ('Prestador PJ', 'Prestador de serviços PJ');

-- 1.3: Padronizar nomes de grupos em lancamentos
UPDATE lancamentos
SET grupo_item = 'Alimentos e Bebidas', updated_at = NOW()
WHERE LOWER(grupo_item) = 'alimentos e bebidas';

UPDATE lancamentos
SET grupo_item = 'Outras Despesas Administrativas FLEM', updated_at = NOW()
WHERE LOWER(grupo_item) = 'outras despesas administrativas flem';

UPDATE lancamentos
SET grupo_item = 'Prestador de Serviços PJ', updated_at = NOW()
WHERE grupo_item IN ('Prestador PJ', 'Prestador de serviços PJ');

-- 1.4: Adicionar constraint de unicidade
CREATE UNIQUE INDEX IF NOT EXISTS idx_orcamento_total_unico 
ON orcamento_total_projeto (item_nome, grupo_item) 
WHERE ativo = true;

-- ============================================================
-- FASE 2: TRIGGERS DE NORMALIZAÇÃO AUTOMÁTICA
-- ============================================================

-- 2.1: Função para normalizar antes de inserir/atualizar
CREATE OR REPLACE FUNCTION normalizar_antes_insert()
RETURNS TRIGGER AS $$
BEGIN
  NEW.item_nome = normalizar_nome_item(NEW.item_nome);
  NEW.grupo_item = normalizar_nome_item(NEW.grupo_item);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 2.2: Trigger para orcamento_total_projeto
DROP TRIGGER IF EXISTS trigger_normalizar_orcamento_total ON orcamento_total_projeto;
CREATE TRIGGER trigger_normalizar_orcamento_total
  BEFORE INSERT OR UPDATE ON orcamento_total_projeto
  FOR EACH ROW
  EXECUTE FUNCTION normalizar_antes_insert();

-- 2.3: Trigger para lancamentos
DROP TRIGGER IF EXISTS trigger_normalizar_lancamentos ON lancamentos;
CREATE TRIGGER trigger_normalizar_lancamentos
  BEFORE INSERT OR UPDATE ON lancamentos
  FOR EACH ROW
  EXECUTE FUNCTION normalizar_antes_insert();

-- 2.4: Trigger para orcamento_detalhado
DROP TRIGGER IF EXISTS trigger_normalizar_orcamento_detalhado ON orcamento_detalhado;
CREATE TRIGGER trigger_normalizar_orcamento_detalhado
  BEFORE INSERT OR UPDATE ON orcamento_detalhado
  FOR EACH ROW
  EXECUTE FUNCTION normalizar_antes_insert();

-- ============================================================
-- FASE 3: VIEW CONSOLIDADA PARA DASHBOARD
-- ============================================================

-- 3.1: Criar view que unifica orcamento_detalhado + orcamento_total_projeto
CREATE OR REPLACE VIEW vw_orcamento_completo AS
WITH meses_projeto AS (
  SELECT unnest(ARRAY[
    '2025-03', '2025-04', '2025-05', '2025-06', '2025-07', '2025-08',
    '2025-09', '2025-10', '2025-11', '2025-12', '2026-01', '2026-02'
  ])::TEXT as ano_mes
),
orcamento_distribuido AS (
  -- Orçamento detalhado onde existe
  SELECT 
    ano::TEXT || '-' || LPAD(
      CASE LOWER(mes)
        WHEN 'março' THEN '03' WHEN 'abril' THEN '04' WHEN 'maio' THEN '05'
        WHEN 'junho' THEN '06' WHEN 'julho' THEN '07' WHEN 'agosto' THEN '08'
        WHEN 'setembro' THEN '09' WHEN 'outubro' THEN '10' WHEN 'novembro' THEN '11'
        WHEN 'dezembro' THEN '12' WHEN 'janeiro' THEN '01' WHEN 'fevereiro' THEN '02'
      END, 2, '0'
    ) as ano_mes,
    item_nome,
    categoria_principal,
    categoria_id,
    SUM(valor_subtotal) as valor_orcado
  FROM orcamento_detalhado
  WHERE ativo = true
  GROUP BY ano, mes, item_nome, categoria_principal, categoria_id
  
  UNION ALL
  
  -- Distribuir orçamento total para meses SEM orçamento detalhado
  SELECT 
    mp.ano_mes,
    otp.item_nome,
    otp.categoria_principal,
    NULL::UUID as categoria_id,
    otp.valor_total_projeto / 12 as valor_orcado
  FROM orcamento_total_projeto otp
  CROSS JOIN meses_projeto mp
  WHERE otp.ativo = true
    AND NOT EXISTS (
      SELECT 1 FROM orcamento_detalhado od
      WHERE normalizar_nome_item(od.item_nome) = normalizar_nome_item(otp.item_nome)
        AND od.ano::TEXT || '-' || LPAD(
          CASE LOWER(od.mes)
            WHEN 'março' THEN '03' WHEN 'abril' THEN '04' WHEN 'maio' THEN '05'
            WHEN 'junho' THEN '06' WHEN 'julho' THEN '07' WHEN 'agosto' THEN '08'
            WHEN 'setembro' THEN '09' WHEN 'outubro' THEN '10' WHEN 'novembro' THEN '11'
            WHEN 'dezembro' THEN '12' WHEN 'janeiro' THEN '01' WHEN 'fevereiro' THEN '02'
          END, 2, '0'
        ) = mp.ano_mes
    )
),
lancamentos_agrupados AS (
  SELECT 
    l.ano::TEXT || '-' || LPAD(
      CASE LOWER(l.mes)
        WHEN 'março' THEN '03' WHEN 'abril' THEN '04' WHEN 'maio' THEN '05'
        WHEN 'junho' THEN '06' WHEN 'julho' THEN '07' WHEN 'agosto' THEN '08'
        WHEN 'setembro' THEN '09' WHEN 'outubro' THEN '10' WHEN 'novembro' THEN '11'
        WHEN 'dezembro' THEN '12' WHEN 'janeiro' THEN '01' WHEN 'fevereiro' THEN '02'
      END, 2, '0'
    ) as ano_mes,
    normalizar_nome_item(l.item) as item_nome,
    SUM(l.realizado) as valor_realizado
  FROM lancamentos l
  GROUP BY l.ano, l.mes, normalizar_nome_item(l.item)
)
SELECT 
  CAST(SUBSTRING(od.ano_mes, 1, 4) AS INTEGER) as ano,
  CASE SUBSTRING(od.ano_mes, 6, 2)
    WHEN '03' THEN 'março' WHEN '04' THEN 'abril' WHEN '05' THEN 'maio'
    WHEN '06' THEN 'junho' WHEN '07' THEN 'julho' WHEN '08' THEN 'agosto'
    WHEN '09' THEN 'setembro' WHEN '10' THEN 'outubro' WHEN '11' THEN 'novembro'
    WHEN '12' THEN 'dezembro' WHEN '01' THEN 'janeiro' WHEN '02' THEN 'fevereiro'
  END as mes,
  od.item_nome,
  od.categoria_principal,
  od.categoria_id,
  COALESCE(od.valor_orcado, 0) as valor_orcado,
  COALESCE(l.valor_realizado, 0) as valor_realizado,
  COALESCE(od.valor_orcado, 0) - COALESCE(l.valor_realizado, 0) as saldo
FROM orcamento_distribuido od
LEFT JOIN lancamentos_agrupados l ON 
  l.ano_mes = od.ano_mes
  AND normalizar_nome_item(l.item_nome) = normalizar_nome_item(od.item_nome);

