-- Migration: 20251112224107_eb0ffab5-95b1-4ffd-8f4f-4b1b612adb4d.sql
-- Migração para vincular lançamentos às categorias
-- Etapa 1: Vincular por itens_despesa (para itens cadastrados)
UPDATE lancamentos l
SET categoria_id = id.categoria_id
FROM itens_despesa id
WHERE l.categoria_id IS NULL
  AND normalizar_nome_item(l.item) = normalizar_nome_item(id.nome)
  AND id.categoria_id IS NOT NULL;

-- Etapa 2: Vincular por mapeamento de grupo_item (para itens não cadastrados)
UPDATE lancamentos l
SET categoria_id = c.id
FROM categorias c
WHERE l.categoria_id IS NULL
  AND (
    -- Locação de Infraestrutura
    (LOWER(l.grupo_item) ILIKE '%locação%infraestrutura%' AND c.nome = 'Locação de Infraestrutura')
    OR
    -- Alimentos e bebidas
    (LOWER(l.grupo_item) ILIKE '%alimentos%bebidas%' AND c.nome = 'Alimentos e bebidas')
    OR
    -- Prestador de Serviços PJ
    ((LOWER(l.grupo_item) ILIKE '%prestador%pj%' OR LOWER(l.grupo_item) ILIKE '%prestador%serviços%pj%') 
     AND c.nome = 'Prestador de Serviços PJ')
    OR
    -- Transporte
    (LOWER(l.grupo_item) ILIKE '%transporte%' AND c.nome = 'Transporte')
    OR
    -- Comunicação Visual
    (LOWER(l.grupo_item) ILIKE '%comunicação%visual%' AND c.nome = 'Comunicação Visual')
    OR
    -- Despesas com equipe de projeto
    (LOWER(l.grupo_item) ILIKE '%despesas%equipe%projeto%' AND c.nome = 'Despesas com equipe de projeto')
    OR
    -- Prestador de Serviços PF
    ((LOWER(l.grupo_item) ILIKE '%prestador%pf%' OR LOWER(l.grupo_item) ILIKE '%prestador%serviços%pf%') 
     AND c.nome = 'Prestador de serviços PF')
    OR
    -- Publicidade
    (LOWER(l.grupo_item) ILIKE '%publicidade%' AND c.nome = 'Publicidade')
    OR
    -- Viagens
    (LOWER(l.grupo_item) ILIKE '%viagens%' AND c.nome = 'Viagens')
    OR
    -- Equipamentos
    (LOWER(l.grupo_item) ILIKE '%equipamentos%' AND c.nome = 'Equipamentos')
    OR
    -- Equipe técnica (variações)
    ((LOWER(l.grupo_item) ILIKE '%equipe%técnica%' OR LOWER(l.grupo_item) ILIKE '%equipe%tecnica%') 
     AND c.nome = 'Equipe técnica')
    OR
    -- Despesas gerais administrativas
    ((LOWER(l.grupo_item) ILIKE '%despesas%gerais%' OR LOWER(l.grupo_item) ILIKE '%administrativas%') 
     AND c.nome = 'Despesas gerais administrativas')
  );

