-- Criar tabela de consumo mensal de itens
CREATE TABLE IF NOT EXISTS public.consumo_itens_mensal (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  
  -- Identificação do item
  item_id UUID NOT NULL REFERENCES public.orcamento_total_projeto(id) ON DELETE CASCADE,
  item_nome TEXT NOT NULL,
  grupo_item TEXT NOT NULL,
  categoria_principal TEXT NOT NULL,
  
  -- Período
  mes TEXT NOT NULL CHECK (mes IN ('março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro', 'janeiro', 'fevereiro')),
  ano INTEGER NOT NULL CHECK (ano BETWEEN 2025 AND 2026),
  
  -- Quantidade consumida
  quantidade_consumida NUMERIC NOT NULL DEFAULT 0 CHECK (quantidade_consumida >= 0),
  unidade TEXT,
  
  -- Observações
  observacao TEXT,
  
  -- Auditoria
  criado_por UUID,
  criado_em TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  atualizado_em TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  
  -- Constraint: Um registro por item/mês/ano
  UNIQUE(item_id, mes, ano)
);

-- Índices para performance
CREATE INDEX idx_consumo_itens_mes_ano ON public.consumo_itens_mensal(mes, ano);
CREATE INDEX idx_consumo_itens_item_id ON public.consumo_itens_mensal(item_id);
CREATE INDEX idx_consumo_itens_categoria ON public.consumo_itens_mensal(categoria_principal);

-- Trigger para atualizar atualizado_em
CREATE TRIGGER update_consumo_itens_updated_at
  BEFORE UPDATE ON public.consumo_itens_mensal
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

-- RLS Policies
ALTER TABLE public.consumo_itens_mensal ENABLE ROW LEVEL SECURITY;

-- Todos usuários autenticados podem visualizar
CREATE POLICY "Authenticated users can view consumo"
  ON public.consumo_itens_mensal
  FOR SELECT
  USING (true);

-- Gestores podem criar/atualizar/deletar
CREATE POLICY "Gestores can manage consumo"
  ON public.consumo_itens_mensal
  FOR ALL
  USING (
    has_role(auth.uid(), 'admin'::app_role) OR 
    has_role(auth.uid(), 'gestor_financeiro'::app_role) OR 
    has_role(auth.uid(), 'coordenador_campo'::app_role)
  );

-- Comentários
COMMENT ON TABLE public.consumo_itens_mensal IS 'Armazena quantidades consumidas mensalmente de cada item do projeto';
COMMENT ON COLUMN public.consumo_itens_mensal.quantidade_consumida IS 'Quantidade física consumida no mês (ex: 100 cadeiras, 50 mesas)';

