-- Criar função que atualiza campo "atualizado_em" (português)
CREATE OR REPLACE FUNCTION public.update_atualizado_em_column()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  NEW.atualizado_em = NOW();
  RETURN NEW;
END;
$$;

-- Remover trigger antigo que usava função incorreta
DROP TRIGGER IF EXISTS update_consumo_itens_updated_at ON public.consumo_itens_mensal;

-- Criar novo trigger que usa a função correta
CREATE TRIGGER update_consumo_itens_atualizado_em
  BEFORE UPDATE ON public.consumo_itens_mensal
  FOR EACH ROW
  EXECUTE FUNCTION update_atualizado_em_column();

-- Migration: 20251119182539_82dff667-0bd7-4e8f-b6b0-a41ecad19ce3.sql
-- ====================================================
-- ETAPA 1: Criar função de normalização de texto
-- ====================================================
CREATE OR REPLACE FUNCTION unaccent_lower(text)
RETURNS text AS $$
  SELECT lower(
    translate($1, 
      'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ',
      'aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'
    )
  );
$$ LANGUAGE sql IMMUTABLE;

-- ====================================================
-- ETAPA 2: Criar função RPC para buscar lançamentos por item
-- ====================================================
CREATE OR REPLACE FUNCTION buscar_lancamentos_por_item(
  p_item_nome TEXT,
  p_ano INTEGER
)
RETURNS TABLE(realizado NUMERIC) AS $$
BEGIN
  RETURN QUERY
  SELECT l.realizado
  FROM lancamentos l
  WHERE l.ano = p_ano
    AND (
      -- Matching exato normalizado
      unaccent_lower(l.item) = unaccent_lower(p_item_nome)
      OR
      -- Matching parcial bidirecional
      unaccent_lower(l.item) LIKE '%' || unaccent_lower(p_item_nome) || '%'
      OR
      unaccent_lower(p_item_nome) LIKE '%' || unaccent_lower(l.item) || '%'
    );
END;
$$ LANGUAGE plpgsql STABLE;

-- ====================================================
-- ETAPA 3: Correção de dados históricos
-- ====================================================

-- 3.1. Corrigir "Equipe Logistica" → "Equipe Logística"
UPDATE lancamentos
SET item = 'Equipe Logística'
WHERE unaccent_lower(item) = 'equipe logistica'
  AND EXISTS (
    SELECT 1 FROM itens_despesa i
    WHERE i.nome = 'Equipe Logística'
      AND i.categoria_id = lancamentos.categoria_id
  );

-- 3.2. Corrigir "Gradil" → "Locação de gradil"
UPDATE lancamentos
SET item = 'Locação de gradil'
WHERE unaccent_lower(item) = 'gradil'
  AND EXISTS (
    SELECT 1 FROM itens_despesa i
    WHERE i.nome = 'Locação de gradil'
      AND i.categoria_id = lancamentos.categoria_id
  );

-- 3.3. Corrigir "Auxiliar Serviços Gerais" → "Auxiliar de Serviços Gerais"
UPDATE lancamentos
SET item = 'Auxiliar de Serviços Gerais'
WHERE unaccent_lower(item) LIKE '%auxiliar%servi%gerais%'
  AND unaccent_lower(item) NOT LIKE '%de%'
  AND EXISTS (
    SELECT 1 FROM itens_despesa i
    WHERE i.nome = 'Auxiliar de Serviços Gerais'
      AND i.categoria_id = lancamentos.categoria_id
  );

-- 3.4. Corrigir "Interprete libras" → "Intérprete de Libras"
UPDATE lancamentos
SET item = 'Intérprete de Libras'
WHERE unaccent_lower(item) LIKE '%interprete%libras%'
  AND unaccent_lower(item) NOT LIKE '%de%'
  AND EXISTS (
    SELECT 1 FROM itens_despesa i
    WHERE i.nome = 'Intérprete de Libras'
      AND i.categoria_id = lancamentos.categoria_id
  );

-- 3.5. Corrigir variações de "Copo de água"
UPDATE lancamentos l
SET item = i.nome
FROM itens_despesa i
WHERE l.categoria_id = i.categoria_id
  AND unaccent_lower(l.item) LIKE '%copo%agua%'
  AND unaccent_lower(i.nome) LIKE '%copo%agua%';

-- 3.6. Corrigir "Encargos Sociais" → "Encargos sociais e trabalhistas"
UPDATE lancamentos
SET item = 'Encargos sociais e trabalhistas (Prestador de Serviço PF)'
WHERE unaccent_lower(item) LIKE '%encargos%'
  AND unaccent_lower(item) NOT LIKE '%trabalhistas%'
  AND EXISTS (
    SELECT 1 FROM itens_despesa i
    WHERE i.nome = 'Encargos sociais e trabalhistas (Prestador de Serviço PF)'
      AND i.categoria_id = lancamentos.categoria_id
  );

-- 3.7. Corrigir nomes de itens que contêm o nome cadastrado mas com texto extra
UPDATE lancamentos l
SET item = i.nome
FROM itens_despesa i
WHERE l.categoria_id = i.categoria_id
  AND unaccent_lower(l.item) LIKE '%' || unaccent_lower(i.nome) || '%'
  AND unaccent_lower(l.item) != unaccent_lower(i.nome)
  AND LENGTH(l.item) > LENGTH(i.nome);

-- 3.8. Corrigir matching reverso (item cadastrado contém nome do lançamento)
UPDATE lancamentos l
SET item = i.nome
FROM itens_despesa i
WHERE l.categoria_id = i.categoria_id
  AND unaccent_lower(i.nome) LIKE '%' || unaccent_lower(l.item) || '%'
  AND unaccent_lower(l.item) != unaccent_lower(i.nome)
  AND LENGTH(i.nome) > LENGTH(l.item);

