-- CORREÇÃO: Ajustar categoria_id de itens cadastrados incorretamente
-- ====================================================

-- Corrigir "Tradução da redação" de Prestador de Serviços PJ para Publicidade
UPDATE itens_despesa
SET categoria_id = (
  SELECT id FROM categorias WHERE nome ILIKE '%Publicidade%' LIMIT 1
)
WHERE nome ILIKE '%Tradução da redação%'
  AND categoria_id = (
    SELECT id FROM categorias WHERE nome ILIKE '%Prestador%Servi%PJ%' LIMIT 1
  );

