-- Migration: 20251119191637_6ed2cc90-b738-4d03-bfa4-f635e4b89694.sql
-- ====================================================
-- CORREÇÃO: Função buscar_lancamentos_por_item com matching mais preciso
-- ====================================================

CREATE OR REPLACE FUNCTION public.buscar_lancamentos_por_item(p_item_nome text, p_ano integer)
RETURNS TABLE(realizado numeric)
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT l.realizado
  FROM lancamentos l
  WHERE l.ano = p_ano
    AND (
      -- 1. Matching exato normalizado (prioridade máxima)
      unaccent_lower(l.item) = unaccent_lower(p_item_nome)
      OR
      -- 2. Matching parcial apenas se o termo pesquisado for o MAIOR
      -- Evita que "Ônibus" capture "Envelopamento/Ônibus"
      (
        unaccent_lower(l.item) LIKE '%' || unaccent_lower(p_item_nome) || '%'
        AND LENGTH(unaccent_lower(p_item_nome)) > LENGTH(unaccent_lower(l.item)) * 0.5
        AND NOT (l.item LIKE '%/%' AND position('/' in p_item_nome) = 0)
      )
      OR
      -- 3. Matching reverso apenas para itens simples (sem "/")
      -- Permite que "Envelopamento/Ônibus" capture lançamentos de "Envelopamento"
      (
        unaccent_lower(p_item_nome) LIKE '%' || unaccent_lower(l.item) || '%'
        AND position('/' in l.item) = 0
      )
    );
END;
$function$;

