-- Função auxiliar para normalizar nomes (remove parênteses e conteúdo, espaços extras)
CREATE OR REPLACE FUNCTION public.normalizar_nome_completo(nome TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  -- Remove parênteses e seu conteúdo, remove espaços extras, normaliza acentos
  RETURN TRIM(
    REGEXP_REPLACE(
      unaccent_lower(REGEXP_REPLACE(nome, '\([^)]*\)', '', 'g')),
      '\s+', ' ', 'g'
    )
  );
END;
$$;

-- Recriar buscar_lancamentos_por_item com matching flexível
CREATE OR REPLACE FUNCTION public.buscar_lancamentos_por_item(p_item_nome TEXT, p_ano INTEGER)
RETURNS TABLE(realizado NUMERIC)
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $$
DECLARE
  v_nome_normalizado TEXT;
BEGIN
  -- Normalizar o nome pesquisado
  v_nome_normalizado := normalizar_nome_completo(p_item_nome);
  
  RETURN QUERY
  SELECT l.realizado
  FROM lancamentos l
  WHERE l.ano = p_ano
    AND (
      -- 1. Matching exato normalizado (prioridade máxima)
      normalizar_nome_completo(l.item) = v_nome_normalizado
      OR
      -- 2. Matching parcial controlado com nome normalizado
      (
        normalizar_nome_completo(l.item) LIKE '%' || v_nome_normalizado || '%'
        AND LENGTH(v_nome_normalizado) >= LENGTH(normalizar_nome_completo(l.item)) * 0.8
      )
    );
END;
$$;

