-- Migration: 20251125131245_6d5f29fb-57fa-4f78-bd15-f8977f7e86a7.sql
-- ====================================================
-- CORREÇÃO: Matching de itens com parênteses (3 níveis)
-- ====================================================

-- Recriar buscar_orcamento_por_item com estratégia de 3 níveis
CREATE OR REPLACE FUNCTION public.buscar_orcamento_por_item(p_item_nome TEXT, p_categoria_nome TEXT)
RETURNS TABLE(valor_total_projeto NUMERIC)
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $$
DECLARE
  v_nome_normalizado TEXT;
  v_tem_parenteses BOOLEAN;
BEGIN
  -- Normalizar o nome pesquisado
  v_nome_normalizado := normalizar_nome_completo(p_item_nome);
  
  -- Verificar se o nome buscado tem parênteses
  v_tem_parenteses := p_item_nome LIKE '%(%';
  
  RETURN QUERY
  SELECT otp.valor_total_projeto
  FROM orcamento_total_projeto otp
  WHERE otp.ativo = true
    AND unaccent_lower(otp.categoria_principal) LIKE '%' || unaccent_lower(p_categoria_nome) || '%'
    AND (
      -- Nível 1: Matching exato original (prioridade máxima)
      unaccent_lower(otp.item_nome) = unaccent_lower(p_item_nome)
      OR
      -- Nível 2: Matching com controle de parênteses
      (
        -- Se item buscado NÃO tem parênteses, NÃO incluir itens que tenham
        (NOT v_tem_parenteses AND otp.item_nome NOT LIKE '%(%' AND 
         normalizar_nome_completo(otp.item_nome) = v_nome_normalizado)
        OR
        -- Se item buscado TEM parênteses, permitir normalização
        (v_tem_parenteses AND normalizar_nome_completo(otp.item_nome) = v_nome_normalizado)
      )
      OR
      -- Nível 3: Matching parcial controlado (fallback para typos)
      (
        normalizar_nome_completo(otp.item_nome) LIKE '%' || v_nome_normalizado || '%'
        AND LENGTH(v_nome_normalizado) >= LENGTH(normalizar_nome_completo(otp.item_nome)) * 0.8
        AND (v_tem_parenteses OR otp.item_nome NOT LIKE '%(%')
      )
    );
END;
$$;

