-- Migration: 20260113184128_82c951e9-51e0-478a-94ad-93f22342a04a.sql
-- Atualizar função buscar_orcamento_por_item com filtro de contrato
CREATE OR REPLACE FUNCTION public.buscar_orcamento_por_item(p_item_nome text, p_categoria_nome text, p_contrato_id uuid DEFAULT NULL)
 RETURNS TABLE(valor_total_projeto numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nome_normalizado TEXT;
  v_tem_parenteses BOOLEAN;
BEGIN
  -- Normalizar o nome pesquisado
  v_nome_normalizado := normalizar_nome_completo(p_item_nome);
  
  -- Verificar se o nome buscado tem parênteses
  v_tem_parenteses := p_item_nome LIKE '%(%';
  
  RETURN QUERY
  WITH nivel1 AS (
    -- Nível 1: Matching exato original (case-insensitive, sem remover parênteses)
    SELECT otp.valor_total_projeto
    FROM orcamento_total_projeto otp
    WHERE otp.ativo = true
      AND unaccent_lower(otp.categoria_principal) LIKE '%' || unaccent_lower(p_categoria_nome) || '%'
      AND unaccent_lower(otp.item_nome) = unaccent_lower(p_item_nome)
      AND (p_contrato_id IS NULL OR otp.contrato_id = p_contrato_id)
  ),
  nivel2 AS (
    -- Nível 2: Matching com controle de parênteses (apenas se Nível 1 vazio)
    SELECT otp.valor_total_projeto
    FROM orcamento_total_projeto otp
    WHERE NOT EXISTS (SELECT 1 FROM nivel1)
      AND otp.ativo = true
      AND unaccent_lower(otp.categoria_principal) LIKE '%' || unaccent_lower(p_categoria_nome) || '%'
      AND (p_contrato_id IS NULL OR otp.contrato_id = p_contrato_id)
      AND (
        -- Se item buscado NÃO tem parênteses, NÃO incluir itens que tenham
        (NOT v_tem_parenteses AND otp.item_nome NOT LIKE '%(%' AND 
         normalizar_nome_completo(otp.item_nome) = v_nome_normalizado)
        OR
        -- Se item buscado TEM parênteses, permitir normalização
        (v_tem_parenteses AND normalizar_nome_completo(otp.item_nome) = v_nome_normalizado)
      )
  ),
  nivel3 AS (
    -- Nível 3: Matching parcial controlado (apenas se Níveis 1 e 2 vazios)
    SELECT otp.valor_total_projeto
    FROM orcamento_total_projeto otp
    WHERE NOT EXISTS (SELECT 1 FROM nivel1)
      AND NOT EXISTS (SELECT 1 FROM nivel2)
      AND otp.ativo = true
      AND unaccent_lower(otp.categoria_principal) LIKE '%' || unaccent_lower(p_categoria_nome) || '%'
      AND (p_contrato_id IS NULL OR otp.contrato_id = p_contrato_id)
      AND normalizar_nome_completo(otp.item_nome) LIKE '%' || v_nome_normalizado || '%'
      AND LENGTH(v_nome_normalizado) >= LENGTH(normalizar_nome_completo(otp.item_nome)) * 0.8
      AND (v_tem_parenteses OR otp.item_nome NOT LIKE '%(%')
  )
  SELECT * FROM nivel1
  UNION ALL
  SELECT * FROM nivel2
  UNION ALL
  SELECT * FROM nivel3;
END;
$function$;

-- Atualizar função buscar_lancamentos_por_item com filtro de contrato
CREATE OR REPLACE FUNCTION public.buscar_lancamentos_por_item(p_item_nome text, p_ano integer, p_contrato_id uuid DEFAULT NULL)
 RETURNS TABLE(realizado numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nome_normalizado TEXT;
  v_tem_parenteses BOOLEAN;
BEGIN
  -- Normalizar o nome pesquisado
  v_nome_normalizado := normalizar_nome_completo(p_item_nome);
  
  -- Verificar se o nome buscado tem parênteses
  v_tem_parenteses := p_item_nome LIKE '%(%';
  
  RETURN QUERY
  WITH nivel1 AS (
    -- Nível 1: Matching exato original (case-insensitive, sem remover parênteses)
    SELECT l.realizado
    FROM lancamentos l
    WHERE l.ano = p_ano
      AND unaccent_lower(l.item) = unaccent_lower(p_item_nome)
      AND (p_contrato_id IS NULL OR l.contrato_id = p_contrato_id)
  ),
  nivel2 AS (
    -- Nível 2: Matching com controle de parênteses (apenas se Nível 1 vazio)
    SELECT l.realizado
    FROM lancamentos l
    WHERE NOT EXISTS (SELECT 1 FROM nivel1)
      AND l.ano = p_ano
      AND (p_contrato_id IS NULL OR l.contrato_id = p_contrato_id)
      AND (
        -- Se item buscado NÃO tem parênteses, NÃO incluir itens que tenham
        (NOT v_tem_parenteses AND l.item NOT LIKE '%(%' AND 
         normalizar_nome_completo(l.item) = v_nome_normalizado)
        OR
        -- Se item buscado TEM parênteses, permitir normalização
        (v_tem_parenteses AND normalizar_nome_completo(l.item) = v_nome_normalizado)
      )
  ),
  nivel3 AS (
    -- Nível 3: Matching parcial controlado (apenas se Níveis 1 e 2 vazios)
    SELECT l.realizado
    FROM lancamentos l
    WHERE NOT EXISTS (SELECT 1 FROM nivel1)
      AND NOT EXISTS (SELECT 1 FROM nivel2)
      AND l.ano = p_ano
      AND (p_contrato_id IS NULL OR l.contrato_id = p_contrato_id)
      AND normalizar_nome_completo(l.item) LIKE '%' || v_nome_normalizado || '%'
      AND LENGTH(v_nome_normalizado) >= LENGTH(normalizar_nome_completo(l.item)) * 0.8
      AND (v_tem_parenteses OR l.item NOT LIKE '%(%')
  )
  SELECT * FROM nivel1
  UNION ALL
  SELECT * FROM nivel2
  UNION ALL
  SELECT * FROM nivel3;
END;
$function$;

