-- 2) Função de notificação em mudança de status
CREATE OR REPLACE FUNCTION public.notificar_status_documento_programa()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user RECORD;
BEGIN
  IF TG_OP <> 'UPDATE' OR NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  -- Enviado para revisão -> notificar admins e gestores financeiros
  IF NEW.status = 'em_revisao' THEN
    FOR v_user IN
      SELECT DISTINCT ur.user_id
      FROM public.user_roles ur
      WHERE ur.role IN ('admin','gestor_financeiro')
    LOOP
      VALUES (
        v_user.user_id,
        'documento',
        'Documento aguardando revisão',
        FORMAT('O documento "%s" foi enviado para revisão.', NEW.titulo),
        '/documentos-programa',
        jsonb_build_object('documento_id', NEW.id, 'escopo', NEW.escopo, 'categoria', NEW.categoria)
      );
    END LOOP;
  END IF;

  -- Aprovado -> notificar autor
  IF NEW.status = 'aprovado' AND NEW.uploaded_by IS NOT NULL THEN
    VALUES (
      NEW.uploaded_by,
      'documento',
      'Documento aprovado',
      FORMAT('Seu documento "%s" foi aprovado.', NEW.titulo),
      '/documentos-programa',
      jsonb_build_object('documento_id', NEW.id, 'aprovado_por', NEW.aprovado_por)
    );
  END IF;

  RETURN NEW;
END;
$$;

