SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user RECORD;
  v_payload JSONB;
  v_email_user RECORD;
BEGIN
  IF TG_OP <> 'UPDATE' OR NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  -- Enviado para revisão -> notificar admins e gestores financeiros
  IF NEW.status = 'em_revisao' THEN
    FOR v_user IN
