        '/documentos-programa',
        jsonb_build_object('documento_id', NEW.id, 'escopo', NEW.escopo, 'categoria', NEW.categoria)
      );

      -- E-mail (se usuário tiver notificações por e-mail ativadas)
      BEGIN
        SELECT id, email, notificacoes_email INTO v_email_user
        FROM public.profiles WHERE id = v_user.user_id;

        IF v_email_user.notificacoes_email = true THEN
          v_payload := jsonb_build_object(
            'user_id', v_email_user.id,
            'titulo', 'Documento aguardando revisão',
            'mensagem', FORMAT('O documento "%s" foi enviado para sua revisão.', NEW.titulo),
            'tipo', 'documento',
            'link', 'https://gbsrxqvlfaixyjjmimqs.supabase.co/documentos-programa'
          );
          PERFORM net.http_post(
            url := 'https://gbsrxqvlfaixyjjmimqs.supabase.co/functions/v1/enviar-notificacao-email',
            headers := jsonb_build_object(
              'Content-Type', 'application/json',
              'Authorization', 'Bearer ' || current_setting('request.headers', true)::json->>'authorization'
            ),
            body := v_payload
          );
        END IF;
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Erro ao enviar e-mail de revisão: %', SQLERRM;
      END;
    END LOOP;
  END IF;

  -- Aprovado -> notificar autor (in-app + e-mail)
  IF NEW.status = 'aprovado' AND NEW.uploaded_by IS NOT NULL THEN
    VALUES (
      NEW.uploaded_by,
      'documento',
      'Documento aprovado',
      FORMAT('Seu documento "%s" foi aprovado.', NEW.titulo),
      '/documentos-programa',
      jsonb_build_object('documento_id', NEW.id, 'aprovado_por', NEW.aprovado_por)
    );

    BEGIN
      SELECT id, email, notificacoes_email INTO v_email_user
      FROM public.profiles WHERE id = NEW.uploaded_by;

      IF v_email_user.notificacoes_email = true THEN
        v_payload := jsonb_build_object(
          'user_id', v_email_user.id,
          'titulo', 'Documento aprovado',
          'mensagem', FORMAT('Seu documento "%s" foi aprovado.', NEW.titulo),
          'tipo', 'documento',
          'link', 'https://gbsrxqvlfaixyjjmimqs.supabase.co/documentos-programa'
        );
        PERFORM net.http_post(
          url := 'https://gbsrxqvlfaixyjjmimqs.supabase.co/functions/v1/enviar-notificacao-email',
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || current_setting('request.headers', true)::json->>'authorization'
          ),
          body := v_payload
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Erro ao enviar e-mail de aprovação: %', SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$$;

