CREATE OR REPLACE FUNCTION public.notificar_status_documento_programa()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user RECORD;
  v_payload JSONB;
  v_email_user RECORD;
  v_msg_revisao TEXT;
  v_msg_aprovado TEXT;
  v_obs_suffix TEXT;
BEGIN
  IF TG_OP <> 'UPDATE' OR NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  v_obs_suffix := CASE
    WHEN NEW.observacao_revisao IS NOT NULL AND length(trim(NEW.observacao_revisao)) > 0
      THEN FORMAT(' Observação: %s', NEW.observacao_revisao)
    ELSE ''
  END;

  IF NEW.status = 'em_revisao' THEN
    v_msg_revisao := FORMAT('O documento "%s" foi enviado para revisão.%s', NEW.titulo, v_obs_suffix);

    FOR v_user IN
      SELECT DISTINCT ur.user_id
      FROM public.user_roles ur
      WHERE ur.role IN ('admin','gestor_financeiro')
    LOOP
      VALUES (
        v_user.user_id,
        'documento',
        'Documento aguardando revisão',
        v_msg_revisao,
        '/gestao/documentos-programa',
        jsonb_build_object(
          'documento_id', NEW.id,
          'escopo', NEW.escopo,
          'categoria', NEW.categoria,
          'observacao', NEW.observacao_revisao
        )
      );

      BEGIN
        SELECT id, email, notificacoes_email INTO v_email_user
        FROM public.profiles WHERE id = v_user.user_id;

        IF v_email_user.notificacoes_email = true THEN
          v_payload := jsonb_build_object(
            'user_id', v_email_user.id,
            'titulo', 'Documento aguardando revisão',
            'mensagem', v_msg_revisao,
            'tipo', 'documento',
            'link', '/gestao/documentos-programa'
          );
          PERFORM net.http_post(
            url := 'https://gbsrxqvlfaixyjjmimqs.supabase.co/functions/v1/enviar-notificacao-email',
            headers := jsonb_build_object('Content-Type', 'application/json'),
            body := v_payload
          );
        END IF;
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Erro ao enviar e-mail de revisão: %', SQLERRM;
      END;
    END LOOP;
  END IF;

  IF NEW.status = 'aprovado' AND NEW.uploaded_by IS NOT NULL THEN
    v_msg_aprovado := FORMAT('Seu documento "%s" foi aprovado.%s', NEW.titulo, v_obs_suffix);

    VALUES (
      NEW.uploaded_by,
      'documento',
      'Documento aprovado',
      v_msg_aprovado,
      '/gestao/documentos-programa',
      jsonb_build_object(
        'documento_id', NEW.id,
        'aprovado_por', NEW.aprovado_por,
        'observacao', NEW.observacao_revisao
      )
    );

    BEGIN
      SELECT id, email, notificacoes_email INTO v_email_user
      FROM public.profiles WHERE id = NEW.uploaded_by;

      IF v_email_user.notificacoes_email = true THEN
        v_payload := jsonb_build_object(
          'user_id', v_email_user.id,
          'titulo', 'Documento aprovado',
          'mensagem', v_msg_aprovado,
          'tipo', 'documento',
          'link', '/gestao/documentos-programa'
        );
        PERFORM net.http_post(
          url := 'https://gbsrxqvlfaixyjjmimqs.supabase.co/functions/v1/enviar-notificacao-email',
          headers := jsonb_build_object('Content-Type', 'application/json'),
          body := v_payload
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Erro ao enviar e-mail de aprovação: %', SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$function$;

