-- Trigger function: registra eventos no histórico
CREATE OR REPLACE FUNCTION public.registrar_historico_documento_programa()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid;
  v_user_nome text;
  v_evento text;
  v_obs text;
BEGIN
  v_user_id := auth.uid();
  SELECT nome_completo INTO v_user_nome FROM public.profiles WHERE id = v_user_id;

  IF TG_OP = 'INSERT' THEN
    v_evento := 'criado';
    v_obs := NULL;
      documento_id, evento, dados_antes, dados_depois, observacao, user_id, user_nome
    ) VALUES (
      NEW.id, v_evento, NULL, to_jsonb(NEW), v_obs, v_user_id, v_user_nome
    );

    -- Cria versão inicial (v1)
      documento_id, numero_versao, arquivo_path, arquivo_nome,
      tamanho_bytes, mime_type, observacao, created_by
    ) VALUES (
      NEW.id, 1, NEW.arquivo_path, NEW.arquivo_nome,
      NEW.tamanho_bytes, NEW.mime_type, 'Versão inicial', NEW.uploaded_by
    )
    ON CONFLICT (documento_id, numero_versao) DO NOTHING;

    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      v_evento := 'status_alterado';
      v_obs := NEW.observacao_revisao;
    ELSIF NEW.arquivo_path IS DISTINCT FROM OLD.arquivo_path THEN
      v_evento := 'arquivo_substituido';
      v_obs := NULL;
    ELSE
      v_evento := 'editado';
      v_obs := NULL;
    END IF;

      documento_id, evento, dados_antes, dados_depois, observacao, user_id, user_nome
    ) VALUES (
      NEW.id, v_evento, to_jsonb(OLD), to_jsonb(NEW), v_obs, v_user_id, v_user_nome
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
      documento_id, evento, dados_antes, dados_depois, observacao, user_id, user_nome
    ) VALUES (
      OLD.id, 'excluido', to_jsonb(OLD), NULL, NULL, v_user_id, v_user_nome
    );
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;

