-- Trigger: bloquear exclusão de pasta não-vazia
CREATE OR REPLACE FUNCTION public.bloquear_exclusao_pasta_nao_vazia()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.documentos_programa WHERE pasta_id = OLD.id) THEN
    RAISE EXCEPTION 'Pasta não está vazia. Mova ou exclua o conteúdo antes.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.documentos_programa_pastas WHERE parent_id = OLD.id) THEN
    RAISE EXCEPTION 'Pasta não está vazia. Mova ou exclua o conteúdo antes.';
  END IF;
  RETURN OLD;
END;
$$;

CREATE TRIGGER trg_bloquear_exclusao_pasta_nao_vazia
  BEFORE DELETE ON public.documentos_programa_pastas
  FOR EACH ROW EXECUTE FUNCTION public.bloquear_exclusao_pasta_nao_vazia();

-- Trigger: prevenir ciclos em parent_id
CREATE OR REPLACE FUNCTION public.prevenir_ciclo_pastas()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_current uuid;
  v_depth int := 0;
BEGIN
  IF NEW.parent_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.parent_id = NEW.id THEN
    RAISE EXCEPTION 'Uma pasta não pode ser pai de si mesma.';
  END IF;
  v_current := NEW.parent_id;
  WHILE v_current IS NOT NULL AND v_depth < 100 LOOP
    IF v_current = NEW.id THEN
      RAISE EXCEPTION 'Operação criaria ciclo na hierarquia de pastas.';
    END IF;
    SELECT parent_id INTO v_current
    FROM public.documentos_programa_pastas WHERE id = v_current;
    v_depth := v_depth + 1;
  END LOOP;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_prevenir_ciclo_pastas
  BEFORE INSERT OR UPDATE OF parent_id ON public.documentos_programa_pastas
  FOR EACH ROW EXECUTE FUNCTION public.prevenir_ciclo_pastas();

-- Trigger: validar que pasta e documento estão no mesmo escopo/contrato/categoria
CREATE OR REPLACE FUNCTION public.validar_pasta_documento_consistencia()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pasta RECORD;
BEGIN
  IF NEW.pasta_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT escopo, contrato_id, categoria INTO v_pasta
  FROM public.documentos_programa_pastas WHERE id = NEW.pasta_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pasta não encontrada.';
  END IF;
  IF v_pasta.escopo <> NEW.escopo OR
     COALESCE(v_pasta.contrato_id::text,'') <> COALESCE(NEW.contrato_id::text,'') OR
     v_pasta.categoria <> NEW.categoria THEN
    RAISE EXCEPTION 'Pasta selecionada não pertence ao mesmo escopo/contrato/categoria do documento.';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_validar_pasta_documento
  BEFORE INSERT OR UPDATE OF pasta_id, escopo, contrato_id, categoria ON public.documentos_programa
  FOR EACH ROW EXECUTE FUNCTION public.validar_pasta_documento_consistencia();

