-- 3. Trigger de alerta para indicador em risco
CREATE OR REPLACE FUNCTION public.verificar_alerta_indicador_risco()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pct numeric;
  v_desc text;
  v_sev text;
BEGIN
  IF NEW.valor_previsto IS NULL OR NEW.valor_previsto <= 0 THEN
    RETURN NEW;
  END IF;
  v_pct := (COALESCE(NEW.valor_realizado,0) / NEW.valor_previsto) * 100;
  IF v_pct >= 80 THEN
    -- Resolver alertas existentes para este indicador/mes
    UPDATE public.alertas_dashboard
    SET resolvido = true, resolvido_em = now()
    WHERE tipo_alerta = 'indicador_em_risco'
      AND mensagem LIKE 'Indicador ' || NEW.indicador_id::text || ' / M' || NEW.mes || '%'
      AND COALESCE(resolvido, false) = false;
    RETURN NEW;
  END IF;

  v_sev := CASE WHEN v_pct < 50 THEN 'critico' WHEN v_pct < 70 THEN 'alto' ELSE 'medio' END;

  SELECT descricao INTO v_desc FROM public.plano_trabalho_indicadores WHERE id = NEW.indicador_id;

  -- Evitar duplicação ativa por (indicador, mes)
  IF NOT EXISTS (
    SELECT 1 FROM public.alertas_dashboard
    WHERE tipo_alerta = 'indicador_em_risco'
      AND mensagem LIKE 'Indicador ' || NEW.indicador_id::text || ' / M' || NEW.mes || '%'
      AND COALESCE(resolvido, false) = false
  ) THEN
      tipo_alerta, severidade, mensagem, mes, valor_orcado, valor_realizado, delta_percentual, acao_sugerida
    ) VALUES (
      'indicador_em_risco',
      v_sev,
      'Indicador ' || NEW.indicador_id::text || ' / M' || NEW.mes || ' — ' || COALESCE(v_desc,'') || ' executado em ' || ROUND(v_pct,1) || '% do previsto',
      'M' || NEW.mes,
      NEW.valor_previsto,
      NEW.valor_realizado,
      v_pct - 100,
      'Verificar execução física do indicador no Plano de Trabalho.'
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_alerta_indicador_risco ON public.plano_trabalho_cronograma;
CREATE TRIGGER trg_alerta_indicador_risco
AFTER INSERT OR UPDATE ON public.plano_trabalho_cronograma
FOR EACH ROW EXECUTE FUNCTION public.verificar_alerta_indicador_risco();

