  WITH CHECK (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'gestor_financeiro'::app_role));

CREATE TABLE public.pt_caravana_acao_formativa (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  relatorio_id UUID NOT NULL REFERENCES public.pt_caravana_relatorio(id) ON DELETE CASCADE,
  atividade TEXT NOT NULL,
  tema TEXT NOT NULL,
  instituicao TEXT,
  publico TEXT,
  n_participantes INTEGER,
  data TEXT,
  ordem_atividade INTEGER NOT NULL DEFAULT 0,
  ordem_tema INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_pt_carav_acao_rel ON public.pt_caravana_acao_formativa(relatorio_id, ordem_atividade, ordem_tema);
ALTER TABLE public.pt_caravana_acao_formativa ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated view pt_caravana_acao_formativa" ON public.pt_caravana_acao_formativa FOR SELECT TO authenticated USING (true);
CREATE POLICY "Gestores manage pt_caravana_acao_formativa" ON public.pt_caravana_acao_formativa FOR ALL TO authenticated
  USING (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'gestor_financeiro'::app_role))
  WITH CHECK (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'gestor_financeiro'::app_role));

CREATE TRIGGER trg_pt_caravana_rel_upd BEFORE UPDATE ON public.pt_caravana_relatorio FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER trg_pt_caravana_atend_upd BEFORE UPDATE ON public.pt_caravana_atendimento FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER trg_pt_caravana_acao_upd BEFORE UPDATE ON public.pt_caravana_acao_formativa FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();


