-- Tabela de pedidos (cabeçalho)
CREATE TABLE public.pedidos_caravana (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  contrato_id UUID,
  caravana_id UUID,
  titulo TEXT NOT NULL,
  local TEXT,
  data_caravana TEXT,
  solicitante TEXT,
  cargo_solicitante TEXT,
  data_solicitacao DATE DEFAULT CURRENT_DATE,
  status TEXT NOT NULL DEFAULT 'rascunho',
  observacoes TEXT,
  created_by UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Tabela de itens do pedido
CREATE TABLE public.pedidos_caravana_itens (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  pedido_id UUID NOT NULL REFERENCES public.pedidos_caravana(id) ON DELETE CASCADE,
  categoria TEXT NOT NULL,
  item_nome TEXT NOT NULL,
  observacao TEXT,
  unidade TEXT DEFAULT 'un.',
  quantidade NUMERIC NOT NULL DEFAULT 0,
  valor_unitario NUMERIC NOT NULL DEFAULT 0,
