-- Trigger: registrar mudança de status
CREATE OR REPLACE FUNCTION public.registrar_historico_solicitacao_viagem()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_nome text;
BEGIN
  SELECT nome_completo INTO v_user_nome FROM public.profiles WHERE id = auth.uid();
  IF TG_OP = 'INSERT' THEN
    VALUES (NEW.id, 'criada', 'Solicitação criada com status ' || NEW.status, auth.uid(), v_user_nome);
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    VALUES (NEW.id, 'status_alterado',
      'Status alterado de ' || OLD.status || ' para ' || NEW.status,
      auth.uid(), v_user_nome,
      jsonb_build_object('de', OLD.status, 'para', NEW.status));
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_sv_historico
AFTER INSERT OR UPDATE ON public.solicitacoes_viagem
FOR EACH ROW EXECUTE FUNCTION public.registrar_historico_solicitacao_viagem();

-- Trigger: registrar anexo no histórico
CREATE OR REPLACE FUNCTION public.registrar_historico_anexo_viagem()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_nome text;
BEGIN
  SELECT nome_completo INTO v_user_nome FROM public.profiles WHERE id = auth.uid();
  IF TG_OP = 'INSERT' THEN
    VALUES (NEW.solicitacao_id, 'anexo_adicionado',
      'Anexo (' || NEW.tipo || ') adicionado: ' || NEW.arquivo_nome,
      auth.uid(), v_user_nome,
      jsonb_build_object('anexo_id', NEW.id, 'tipo', NEW.tipo));
  ELSIF TG_OP = 'DELETE' THEN
    VALUES (OLD.solicitacao_id, 'anexo_removido',
      'Anexo (' || OLD.tipo || ') removido: ' || OLD.arquivo_nome,
      auth.uid(), v_user_nome,
      jsonb_build_object('anexo_id', OLD.id, 'tipo', OLD.tipo));
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_sva_historico
AFTER INSERT OR DELETE ON public.solicitacao_viagem_anexos
FOR EACH ROW EXECUTE FUNCTION public.registrar_historico_anexo_viagem();

