-- Migration: 20260714185500_fix_anotacoes_calendario_rls.sql
-- Fix RLS policies for anotacoes_calendario
-- Allow all authenticated users to insert/update/delete their own annotations

-- Drop existing restrictive policies
DROP POLICY IF EXISTS "Gestores can insert anotacoes" ON public.anotacoes_calendario;
DROP POLICY IF EXISTS "Gestores can update anotacoes" ON public.anotacoes_calendario;
DROP POLICY IF EXISTS "Gestores can delete anotacoes" ON public.anotacoes_calendario;

-- Allow any authenticated user to insert annotations
CREATE POLICY "Authenticated users can insert anotacoes"
ON public.anotacoes_calendario FOR INSERT
TO authenticated
WITH CHECK (true);

-- Allow users to update their own annotations (admins/gestores can update any)
CREATE POLICY "Users can update own anotacoes"
ON public.anotacoes_calendario FOR UPDATE
TO authenticated
USING (
  created_by = auth.uid()
  OR has_role(auth.uid(), 'admin'::app_role)
  OR has_role(auth.uid(), 'gestor_financeiro'::app_role)
  OR has_role(auth.uid(), 'coordenador_campo'::app_role)
);

-- Allow users to delete their own annotations (admins/gestores can delete any)
CREATE POLICY "Users can delete own anotacoes"
ON public.anotacoes_calendario FOR DELETE
TO authenticated
USING (
  created_by = auth.uid()
  OR has_role(auth.uid(), 'admin'::app_role)
  OR has_role(auth.uid(), 'gestor_financeiro'::app_role)
  OR has_role(auth.uid(), 'coordenador_campo'::app_role)
);


