    {"old":"Carla Saadia","nome":"Carla Saadia Oliveira Moreira","cpf":"79399495515","matr":"14872","ag":"2425","cc":"253083-0"},
    {"old":"Eduarda Carmo","nome":"Eduarda do Carmo Santos Mercês","cpf":"08798040502","matr":"14958","ag":"3566","cc":"55217-8"},
    {"old":"Liliane Nascimento","nome":"Liliane Regina Nascimento Conceição","cpf":"04301085599","matr":"14869","ag":"1425","cc":"160612-3"},
    {"old":"Paulo Henrique","nome":"Paulo Henrique dos Santos","cpf":"56839570525","matr":"14891","ag":"3231","cc":"124508-2"},
    {"old":"Thaiane Cerqueira","nome":"Thaiane Cerqueira Viana","cpf":"85962413539","matr":"15002","ag":"3662","cc":"198070-0"},
    {"old":"Tone Gouveia","nome":"Tone José Pereira Gouveia","cpf":"81668546515","matr":"14095","ag":"3571","cc":"168316-0"},
    {"old":"Vinicius Costa","nome":"Vinicius Assis Costa","cpf":"03098879505","matr":"14874","ag":"3012","cc":"64208-8"}
  ]'::jsonb;
  item jsonb;
  old_cpf text;
BEGIN
