  LOOP
    SELECT cpf INTO old_cpf FROM public.funcionarios WHERE nome_completo = item->>'old';
    IF old_cpf IS NULL AND NOT EXISTS (SELECT 1 FROM public.funcionarios WHERE nome_completo = item->>'old') THEN
      CONTINUE;
