    UPDATE public.funcionarios
      SET nome_completo = item->>'nome',
          cpf = item->>'cpf',
          matricula_flem = item->>'matr',
          agencia_bancaria = item->>'ag',
          conta_bancaria = item->>'cc'
      WHERE nome_completo = item->>'old';

    UPDATE public.solicitacao_viagem_participantes
      SET nome_completo = item->>'nome',
          cpf = item->>'cpf'
      WHERE (old_cpf IS NOT NULL AND cpf = old_cpf)
         OR nome_completo = item->>'old';
  END LOOP;
END $$;

